<?php
require __DIR__.'/app/bootstrap.php';$user=require_permission('view_staff');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    require_permission('manage_users');verify_csrf();try{$name=input('name',120);$code=input('code',40);if($name==='' || !preg_match('/^[a-z0-9-]{2,40}$/',$code))throw new InvalidArgumentException('Enter a department name and a lowercase code using letters, numbers or hyphens.');query('INSERT INTO departments(name,code) VALUES(?,?)',[$name,$code]);flash('Department added.');redirect('departments.php');}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(PDOException $e){if($e->getCode()!=='23000')throw $e;$error='That department name or code already exists.';}
}
$rows=query("SELECT d.id,d.name,s.team_label,COUNT(s.id) total,COALESCE(SUM(s.employment_status='active'),0) active,COALESCE(SUM(s.employment_status='new'),0) new,COALESCE(SUM(s.employment_status='exited'),0) exited FROM departments d LEFT JOIN staff_directory s ON s.department_id=d.id GROUP BY d.id,d.name,s.team_label ORDER BY d.name,s.team_label")->fetchAll();
page_start('Departments & teams',$user);?><div class="section-head"><div><h2>Where everyone belongs</h2><p class="muted">Current assignments, with transfers preserved in employee history.</p></div><a class="button button-secondary" href="history.php">View assignment history</a></div><?php error_notice($error);?><section class="panel flush"><div class="table-wrap"><table><thead><tr><th>Department</th><th>Team</th><th>All staff</th><th>Active</th><th>New</th><th>Exited</th><th>History</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><a href="staff.php?department_id=<?=$row['id']?>"><?=e($row['name'])?></a></td><td><?=e($row['team_label']??'No team yet')?></td><td><?=(int)$row['total']?></td><td><?=(int)$row['active']?></td><td><?=(int)$row['new']?></td><td><?=(int)$row['exited']?></td><td><a href="history.php?department_id=<?=$row['id']?>">Current staff history →</a></td></tr><?php endforeach;?></tbody></table></div></section><?php if(user_can('manage_users')):?><section class="panel"><h2>Add department</h2><form method="post" class="filter-grid"><?php csrf_field();?><label>Name<input name="name" maxlength="120" required></label><label>Code<input name="code" pattern="[a-z0-9-]{2,40}" maxlength="40" required placeholder="customer-support"></label><div><button class="button">Add department</button></div></form></section><?php endif;?><section class="panel"><h2>Department & team transfer history</h2><p class="muted">Assignments at the time of each change, including staff who have since moved elsewhere.</p><?php $transfers=query("SELECT h.*,s.full_name,u.full_name actor_name FROM staff_history h JOIN staff_directory s ON s.id=h.staff_id JOIN users u ON u.id=h.actor_id WHERE h.event_type='updated' AND (NOT (JSON_UNQUOTE(JSON_EXTRACT(h.before_data,'$.department_id')) <=> JSON_UNQUOTE(JSON_EXTRACT(h.after_data,'$.department_id'))) OR NOT (JSON_UNQUOTE(JSON_EXTRACT(h.before_data,'$.team_label')) <=> JSON_UNQUOTE(JSON_EXTRACT(h.after_data,'$.team_label')))) ORDER BY h.effective_date DESC,h.id DESC LIMIT 25")->fetchAll();foreach($transfers as $entry):?><article class="timeline-item"><h3><a href="employee.php?id=<?=$entry['staff_id']?>"><?=e($entry['full_name'])?></a></h3><small><?=e($entry['effective_date'])?> · <?=e($entry['actor_name'])?></small><p><?=e($entry['notes'])?></p><ul class="changes"><?php foreach(history_changes($entry) as $change):?><li><?=e($change)?></li><?php endforeach;?></ul></article><?php endforeach;if(!$transfers):?><p class="muted">No department or team transfers recorded yet.</p><?php endif;?></section><?php page_end();
